fn render_property_signature(node: &PropertySignatureTransport, dest: &mut dyn ::std::fmt::Write) -> ::std::fmt::Result {
    let template = PropertySignatureTemplate {
        accessibility_modifier: match &node.accessibility_modifier {
            Some(v) => OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Transport(v)),
            None => OptionalNonterminalView::Missing,
        },
        name: SingleNonterminalView(::sittir_core::filters::Renderable::Transport(&node.name)),
        optional_marker: if node.optional_marker.unwrap_or(false) {
            OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Text("?"))
        } else {
            OptionalNonterminalView::Missing
        },
        override_modifier: match &node.override_modifier {
            Some(v) => OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Transport(v)),
            None => OptionalNonterminalView::Missing,
        },
        readonly_marker: if node.readonly_marker.unwrap_or(false) {
            OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Text("readonly"))
        } else {
            OptionalNonterminalView::Missing
        },
        static_marker: match &node.static_marker {
            Some(v) => OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Transport(v)),
            None => OptionalNonterminalView::Missing,
        },
        type_: match &node.type_ {
            Some(v) => OptionalNonterminalView::Present(::sittir_core::filters::Renderable::Transport(v)),
            None => OptionalNonterminalView::Missing,
        },
    };
    write_body_property_signature(&template, dest)
}

