fn render_object_type_content(node: &ObjectTypeContentTransport, dest: &mut dyn ::std::fmt::Write) -> ::std::fmt::Result {
    if node.content.as_deref().is_none_or(<[_]>::is_empty) {
        if let Some(text) = node.transport_text.as_deref() {
            return dest.write_str(text);
        }
    }
    let content_owned = node.content.as_deref().unwrap_or(&[]);
    let content_buf: Vec<::sittir_core::filters::Renderable<'_>> = content_owned.iter()
        .map(|t| ::sittir_core::filters::Renderable::Transport(t))
        .collect();
    let template = ObjectTypeContentTemplate {
        content: ListNonterminalView {
            items: content_buf.as_slice(),
            token: match node.separator_kind {
                Some(14) => ",",
                Some(20) => ";",
                _ => "",
            },
            before: "",
            after: "",
            leading: node.delimiter.map(|d| d & 1 != 0).unwrap_or(false),
            trailing: node.delimiter.map(|d| d & 2 != 0).unwrap_or(false),
            head: "",
            tail: "",
        },
    };
    write_body_object_type_content(&template, dest)
}

